using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Reflection;
using UltrakULL.json;
using UnityEngine;

namespace UltrakULL.UI.TranslationBrowser
{
    /// <summary>
    /// Provides language flag sprites from the flag set embedded into the mod
    /// (flags/flags.zip, generated by tools/fetch-flags.ps1 from flagcdn.com,
    /// public domain). The zip is read into memory once; sprites are created
    /// lazily per flag code and cached. A language tag that cannot be mapped to
    /// a flag yields null and the UI falls back to its language-code badge
    /// (the mapping itself lives in the pure FlagCodeMapper).
    ///
    /// SVG is intentionally not used: Unity's runtime UI cannot render SVG
    /// without a vector package (a new dependency, which the project forbids);
    /// 40 px wide PNGs (~1 KB each, whole set ~100 KB) cover the small card
    /// overlay without any addition.
    /// </summary>
    public static class FlagProvider
    {
        private const string ResourceName = "UltrakULL.flags.flags.zip";

        /// <summary>Flag codes available in the embedded set (see FlagCodeMapper).</summary>
        public static HashSet<string> AvailableFlagCodes
        {
            get { return FlagCodeMapper.EmbeddedFlagCodes; }
        }

        public static string MapLanguageToFlagCode(string languageTag)
        {
            return FlagCodeMapper.MapLanguageToFlagCode(languageTag, FlagCodeMapper.EmbeddedFlagCodes);
        }

        private static byte[] _zipBytes;
        private static bool _zipLoadFailed;

        private static readonly Dictionary<string, Sprite> SpriteCache = new Dictionary<string, Sprite>(StringComparer.OrdinalIgnoreCase);

        /// <summary>
        /// Returns the flag sprite for a language tag, or null when the tag has
        /// no flag (or the embedded set could not be loaded). Sprites are cached
        /// per flag code; the whole set is tiny, so no eviction is needed.
        /// </summary>
        public static Sprite GetSprite(string languageTag)
        {
            string code = MapLanguageToFlagCode(languageTag);
            if (code == null)
            {
                return null;
            }

            Sprite cached;
            if (SpriteCache.TryGetValue(code, out cached))
            {
                return cached;
            }

            byte[] png = ReadFlagBytes(code);
            if (png == null)
            {
                return null;
            }

            Texture2D texture = new Texture2D(4, 4, TextureFormat.RGBA32, false);
            texture.name = "UllFlag_" + code;
            if (!ImageConversion.LoadImage(texture, png, false))
            {
                UnityEngine.Object.Destroy(texture);
                Logging.Warn("[FlagProvider] Could not decode the flag '" + code + "'.");
                return null;
            }

            Sprite sprite = Sprite.Create(texture, new Rect(0, 0, texture.width, texture.height), new Vector2(0.5f, 0.5f), 100f, 0, SpriteMeshType.FullRect);
            sprite.name = "UllFlag_" + code;
            SpriteCache[code] = sprite;
            return sprite;
        }

        private static byte[] ReadFlagBytes(string code)
        {
            if (!EnsureZipLoaded())
            {
                return null;
            }

            try
            {
                using (MemoryStream stream = new MemoryStream(_zipBytes))
                using (ZipArchive archive = new ZipArchive(stream, ZipArchiveMode.Read))
                {
                    ZipArchiveEntry entry = archive.GetEntry(code + ".png");
                    if (entry == null)
                    {
                        return null;
                    }

                    using (MemoryStream output = new MemoryStream((int)entry.Length))
                    using (Stream input = entry.Open())
                    {
                        byte[] buffer = new byte[8192];
                        int read;
                        while ((read = input.Read(buffer, 0, buffer.Length)) > 0)
                        {
                            output.Write(buffer, 0, read);
                        }
                        return output.ToArray();
                    }
                }
            }
            catch (Exception e)
            {
                Logging.Warn("[FlagProvider] Could not read the flag '" + code + "' from the embedded zip: " + e.Message);
                return null;
            }
        }

        private static bool EnsureZipLoaded()
        {
            if (_zipBytes != null)
            {
                return true;
            }
            if (_zipLoadFailed)
            {
                return false;
            }

            try
            {
                Assembly assembly = Assembly.GetExecutingAssembly();
                using (Stream stream = assembly.GetManifestResourceStream(ResourceName))
                {
                    if (stream == null)
                    {
                        throw new FileNotFoundException("Embedded resource '" + ResourceName + "' was not found.");
                    }

                    using (MemoryStream memory = new MemoryStream())
                    {
                        stream.CopyTo(memory);
                        _zipBytes = memory.ToArray();
                    }
                }
                Logging.Info("[FlagProvider] Loaded the embedded flag set (" + _zipBytes.Length + " bytes).");
                return true;
            }
            catch (Exception e)
            {
                _zipLoadFailed = true;
                Logging.Warn("[FlagProvider] Could not load the embedded flag set: " + e.Message);
                return false;
            }
        }
    }
}
